      '</div>' +

    '</div>' +
  '</div>';

function calculateAQI(concentration, breakpoints) {
    for (var [cLow, cHigh, iLow, iHigh] of breakpoints) {
        if (concentration >= cLow && concentration <=
            cHigh) {
            var aqi = ((iHigh - iLow) / (cHigh - cLow)) * (
                concentration - cLow) + iLow;
            return Math.round(aqi);
        }
    }
    return null;
}

function getAQI(PM25, PM10) {

    var pm25Breakpoints = [
        [0.0, 12.0, 0, 50],
        [12.1, 35.4, 51, 100],
        [35.5, 55.4, 101, 150],
        [55.5, 150.4, 151, 200],
        [150.5, 250.4, 201, 300],
        [250.5, 350.4, 301, 400],
        [350.5, 500.4, 401, 500],
    ];


    var pm10Breakpoints = [
        [0, 54, 0, 50],
        [55, 154, 51, 100],
        [155, 254, 101, 150],
        [255, 354, 151, 200],
        [355, 424, 201, 300],
        [425, 504, 301, 400],
        [505, 604, 401, 500],
    ];

    var aqiPM25 = calculateAQI(PM25, pm25Breakpoints);
    var aqiPM10 = calculateAQI(PM10, pm10Breakpoints);

    return Math.max(aqiPM25 || 0, aqiPM10 || 0)
}

